package com.optarena.app

import java.util.PriorityQueue

private data class Item(val priority: Int, val order: Long, val value: String)

class StablePriorityQueue {
    private val heap = PriorityQueue<Item>(
        compareBy<Item> { it.priority }.thenBy { it.order },
    )
    private var counter = 0L

    fun push(priority: Int, value: String) {
        heap.add(Item(priority, counter++, value))
    }

    fun pop(): String = heap.poll().value
}

