package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class StablePriorityQueueTest {
    @Test
    fun priorityOrder() {
        val q = StablePriorityQueue()
        q.push(5, "low")
        q.push(1, "high")
        q.push(3, "mid")
        assertEquals("high", q.pop())
        assertEquals("mid", q.pop())
        assertEquals("low", q.pop())
    }

    @Test
    fun equalPriorityIsFifoAcrossManyItems() {
        val q = StablePriorityQueue()
        for (i in 0 until 20) {
            q.push(1, ('a' + i).toString())
        }
        for (i in 0 until 20) {
            assertEquals(('a' + i).toString(), q.pop())
        }
    }
}
